// Go emitter (clients/go, module github.com/xantiagoma/xtandard-image/clients/go):
// writes the generated files of the Go client from the spec.
//
//   zz_generated.go                     package xtandard: the catalogue name tables
//                                       (Catalogue.Canonical, Catalogue.Short), the
//                                       constants (formats, containers, streams,
//                                       sources, signing, encryption, URL rules, query
//                                       keys, imaginary) and the error kinds
//   zz_generated_responses.go           package xtandard: the JSON bodies
//                                       (InfoResponse, ErrorResponse, …)
//   processing/, info/, video/          one typed struct per option form, with an
//     zz_generated.go                   enum type per enum argument
//   imgproxy/zz_generated_methods.go    the fluent chains' per-option methods
//   query/zz_generated_methods.go
//
// This file is the refiner (WP-146): it lowers the neutral model (build.ts)
// into Go nodes (model.ts and lang/go.ts's go.* kinds), which lang/go.ts
// prints. The printed source then goes through gofmt (on PATH with the Go
// toolchain), the official formatter, which aligns struct fields and const
// blocks.

import {
  catalogue,
  type CatalogueModel,
  defaultSegmentFormat,
  enums,
  imaginaryParams,
  nativeVideoKeys,
  type OptionModel,
  refName,
  responseSchemas,
  schemaTypes,
} from "../build.ts";
import { G, GoPrinter, ident } from "../lang/go.ts";
import { type Expr, N, type Node, type Stmt, type TypeRef } from "../model.ts";
import type { CatalogueKind, Emitter, JSONSchema, Spec, SpecArg, SpecForm } from "../spec.ts";

const dir = "clients/go/";
const module = "github.com/xantiagoma/xtandard-image/clients/go";
const printer = new GoPrinter();

/** Pipes Go source through gofmt; the emitted files are what gofmt writes. */
function gofmt(path: string, src: string): string {
  let res: ReturnType<typeof Bun.spawnSync>;
  try {
    res = Bun.spawnSync(["gofmt"], { stdin: new TextEncoder().encode(src), stdout: "pipe", stderr: "pipe" });
  } catch (e) {
    throw new Error(`the Go emitter needs gofmt on PATH (the Go toolchain): ${String(e)}`);
  }
  if (res.exitCode !== 0) {
    throw new Error(`gofmt rejected the generated ${path}:\n${res.stderr?.toString()}\n${src}`);
  }
  return res.stdout!.toString();
}

// ---- nodes ------------------------------------------------------------------------

const t = (name: string) => N.tref(name);
const ptr = (name: string) => N.tref(name, [], { nullable: true });
const id = N.id;
const str = N.str;
const blank = N.blank;
const sel = (pkg: string, name: string) => N.get(id(pkg), name);
const slice = (elem: TypeRef, items: readonly Expr[]) => N.list(items, { type: G.slice(elem) });
const param = (name: string, type: TypeRef, mods: readonly string[] = []) => N.param(name, type, { mods });
const result = (type: TypeRef) => N.param("", type);

/** The file frame: the generated-code notice, what the file holds, the package clause. */
const header = (pkg: string, what: string): Node[] => [
  N.line("Code generated by clients/codegen/emitters/go.ts from clients/spec/spec.json. DO NOT EDIT.\nRun `task clients:generate`."),
  blank(),
  N.line(what),
  blank(),
  G.package(pkg),
  blank(),
];

const kindInfo: Record<CatalogueKind, { pkg: string; catalogue: string; iface: string; method: string }> = {
  processing: { pkg: "processing", catalogue: "CatalogueProcessing", iface: "ProcessingOption", method: "ProcessingOption" },
  info: { pkg: "info", catalogue: "CatalogueInfo", iface: "InfoOption", method: "InfoOption" },
  video: { pkg: "video", catalogue: "CatalogueVideo", iface: "VideoOption", method: "VideoOption" },
};

function optionSummary(o: OptionModel): string {
  return [`URL names: ${o.names.join(", ")} (short: ${o.short}); arguments ${o.spec.syntax}; default ${o.spec.default}.`, `${o.tags.join("; ")}.`].join("\n");
}

/** A function returning a value: func name() T { return value }. */
const getter = (name: string, returns: TypeRef, value: Expr, doc: string) => N.func(name, [], [N.ret(value)], { returns, doc: N.doc(doc) });

/** switch subject { case …: … }, the cases from [matches, body]. */
const switchOf = (subject: Expr | undefined, cases: readonly (readonly [readonly Expr[], readonly Stmt[]])[]) =>
  N.switch(subject, cases.map(([m, b]) => N.case(m, b)));

// ---- package xtandard: tables and constants ---------------------------------

/** One typed string enumeration: `type T string` with a constant per value. */
function enumType(name: string, values: readonly string[], text: string, opts: { doc?: (v: string) => string } = {}): Node[] {
  const seen = new Set<string>();
  const consts = values.map((v) => {
    const c = `${name}${ident(v)}`;
    if (seen.has(c)) throw new Error(`duplicate constant ${c}`);
    seen.add(c);
    return N.const(c, str(v), { type: t(name), ...(opts.doc ? { doc: N.doc(opts.doc(v)) } : {}) });
  });
  return [N.typeAlias(name, t("string"), { doc: N.doc(text) }), blank(), G.group("const", consts, N.doc(`Values of ${name}.`)), blank()];
}

function sliceFunc(name: string, type: string, values: readonly (string | number)[], text: string): Node[] {
  const items = values.map((v) => (typeof v === "string" ? (type === "string" ? str(v) : N.call(N.typeExpr(t(type)), [str(v)])) : N.int(v)));
  return [getter(name, G.slice(t(type)), slice(t(type), items), text), blank()];
}

/** const ( … ) of [doc, name, value, type?] specs (a doc may be empty). */
const constGroup = (doc: string, specs: readonly (readonly [string, string, Expr, TypeRef?])[]) =>
  G.group(
    "const",
    specs.map(([d, name, value, type]) => N.const(name, value, { ...(d ? { doc: N.doc(d) } : {}), ...(type ? { type } : {}) })),
    N.doc(doc),
  );

function catalogueSwitch(cats: readonly CatalogueModel[], body: (c: CatalogueModel) => readonly Stmt[]): Stmt {
  return switchOf(id("c"), cats.map((c) => [[id(kindInfo[c.kind].catalogue)], body(c)] as const));
}

function emitRoot(spec: Spec): Node {
  const cats = (["processing", "info", "video"] as const).map((k) => catalogue(spec, k));
  const cat = param("c", t("Catalogue"));
  const out: Node[] = [...header("xtandard", "Catalogue tables and constants of the client specification.")];
  out.push(N.const("SpecVersion", N.int(spec.spec_version), { doc: N.doc("SpecVersion is the version of clients/spec/spec.json this package was generated from.") }), blank());

  // Catalogue tables.
  out.push(
    N.func(
      "canonicalName",
      [cat, param("name", t("string"))],
      [
        catalogueSwitch(cats, (c) => {
          const byCanonical = new Map<string, string[]>();
          for (const [n, canonical] of c.names) byCanonical.set(canonical, [...(byCanonical.get(canonical) ?? []), n]);
          return [switchOf(id("name"), c.options.map((o) => [byCanonical.get(o.name)!.map(str), [N.ret(str(o.name), N.bool(true))]] as const))];
        }),
        N.ret(str(""), N.bool(false)),
      ],
      { returns: N.ttuple([t("string"), t("bool")]), doc: N.doc("canonicalName returns the canonical name of an option name or alias of a catalogue.") },
    ),
    blank(),
    N.func(
      "shortName",
      [cat, param("canonical", t("string"))],
      [
        catalogueSwitch(cats, (c) => [
          switchOf(
            id("canonical"),
            c.options.filter((o) => o.short !== o.name).map((o) => [[str(o.name)], [N.ret(str(o.short))]] as const),
          ),
        ]),
        N.ret(id("canonical")),
      ],
      { returns: t("string"), doc: N.doc("shortName returns the name builders write by default for a canonical option name.") },
    ),
    blank(),
    N.func(
      "catalogueNames",
      [cat],
      [catalogueSwitch(cats, (c) => [N.ret(slice(t("string"), c.names.map(([n]) => str(n))))]), N.ret(N.null())],
      { returns: G.slice(t("string")), doc: N.doc("catalogueNames returns every option name and alias of a catalogue, sorted.") },
    ),
    blank(),
  );

  // Media.
  const e = enums(spec);
  const s = spec.media.streams;
  out.push(
    ...enumType("ImageFormat", e.image_format.values, "ImageFormat is an output format of the processing format option (an extension of a processing URL)."),
    ...sliceFunc("ImageFormats", "ImageFormat", e.image_format.values, "ImageFormats returns every ImageFormat."),
    ...enumType("VideoContainer", e.video_container.values, "VideoContainer is an output container of /video URLs (their extension)."),
    ...sliceFunc("VideoContainers", "VideoContainer", e.video_container.values, "VideoContainers returns every VideoContainer."),
    ...enumType("StreamProtocol", e.stream_protocol.values, "StreamProtocol is an adaptive streaming protocol: HLS or DASH."),
    N.func(
      "Manifest",
      [],
      [
        switchOf(id("p"), s.protocols.map((p) => [[str(p.name)], [N.ret(str(p.container), str(p.content_type), N.bool(true))]] as const)),
        N.ret(str(""), str(""), N.bool(false)),
      ],
      {
        receiver: param("p", t("StreamProtocol")),
        returns: G.results([param("container", t("VideoContainer")), param("contentType", t("string")), param("ok", t("bool"))]),
        doc: N.doc("Manifest returns the protocol's manifest container (the URL extension) and media type; ok is false for an unknown protocol."),
      },
    ),
    blank(),
    ...enumType("SegmentFormat", e.segment_format.values, "SegmentFormat is a stream segment container: fmp4 (CMAF, the default) or ts (MPEG-TS, HLS only)."),
    N.func(
      "Protocols",
      [],
      [
        switchOf(id("f"), s.segment_formats.map((f) => [[str(f.name)], [N.ret(slice(t("StreamProtocol"), f.protocols.map(str)))]] as const)),
        N.ret(N.null()),
      ],
      {
        receiver: param("f", t("SegmentFormat")),
        returns: G.slice(t("StreamProtocol")),
        doc: N.doc("Protocols returns the stream protocols a segment format is available for (nil for an unknown format)."),
      },
    ),
    blank(),
    constGroup("Stream limits.", [
      ["DefaultSegmentFormat is the segment format the server uses when a URL names none.", "DefaultSegmentFormat", str(defaultSegmentFormat(spec)), t("SegmentFormat")],
      ["MaxRenditions is the most renditions a stream URL may ask for.", "MaxRenditions", N.int(s.max_renditions)],
      ["RenditionMin and RenditionMax bound a rendition (the short side of the frame, in pixels).", "RenditionMin", N.int(s.rendition_min)],
      ["", "RenditionMax", N.int(s.rendition_max)],
      ["SegmentDurationMin and SegmentDurationMax bound the segment duration in seconds.", "SegmentDurationMin", N.int(s.segment_duration_min)],
      ["", "SegmentDurationMax", N.int(s.segment_duration_max)],
    ]),
    blank(),
  );

  // Sources.
  const src = spec.sources;
  out.push(
    ...enumType("SourceScheme", e.source_scheme.values, "SourceScheme is a source scheme the server resolves.", {
      doc: (v) => {
        const sc = src.schemes.find((x) => x.scheme === v)!;
        return `Authority: ${sc.authority}; for example ${sc.example}.`;
      },
    }),
    ...enumType(
      "SourceEncoding",
      e.source_encoding.values,
      "SourceEncoding is how an imgproxy URL carries its source: base64url (the default), plain (percent-escaped) or encrypted (enc/).",
    ),
    N.const("XiNamePattern", str(src.xi_name_pattern), { doc: N.doc("XiNamePattern is the pattern of an xi:// source name (XI_SOURCES).") }),
    blank(),
  );

  // Query dialect.
  const q = spec.query;
  out.push(
    N.const("QueryMount", str(q.mount), { doc: N.doc("QueryMount is the default mount prefix of the query dialect (XI_DIALECTS_QUERY_PREFIX).") }),
    blank(),
    constGroup(
      "Native keys of /q/ image URLs (their aliases too); url, o, format, pdp and xi_sig are written by the query builder.",
      q.image_keys.flatMap((k) =>
        [k.name, ...k.aliases].map(
          (n) => [`QueryKey${ident(n)} is ${n === k.name ? "" : `an alias of ${k.name}: `}${k.doc}`, `QueryKey${ident(n)}`, str(n)] as const,
        ),
      ),
    ),
    blank(),
    N.func(
      "nativeVideoKey",
      [param("name", t("string"))],
      [switchOf(id("name"), nativeVideoKeys(spec).map(([k, v]) => [[str(k)], [N.ret(str(v))]] as const)), N.ret(id("name"))],
      { returns: t("string"), doc: N.doc("nativeVideoKey returns the /q/video key of a /video option name (crop is c, flip is fl).") },
    ),
    blank(),
    ...enumType("ImaginaryEndpoint", e.imaginary_endpoint.values, "ImaginaryEndpoint is an imaginary endpoint of /q/<endpoint>."),
    G.group(
      "const",
      imaginaryParams(spec).map((p) => N.const(`ImaginaryParam${ident(p)}`, str(p))),
      N.doc("Parameters of imaginary endpoints; url and the signatures are written by the query builder."),
    ),
    blank(),
  );

  // Signing and encryption.
  const sg = spec.signing;
  const en = spec.encryption;
  const u = spec.url;
  out.push(
    constGroup("Signing constants.", [
      ["MinSignatureSize and MaxSignatureSize bound a signature size in bytes before encoding (XI_SIGNING_SIZE).", "MinSignatureSize", N.int(sg.min_size)],
      ["", "MaxSignatureSize", N.int(sg.max_size)],
      ["DefaultSignatureSize is the full HMAC-SHA256 size.", "DefaultSignatureSize", N.int(sg.default_size)],
      ["DefaultUnsigned is the signature segment of unsigned imgproxy URLs.", "DefaultUnsigned", str(sg.default_unsigned)],
      ["XiSigParam is the query parameter of xi_sig signatures.", "XiSigParam", str(sg.query_param)],
    ]),
    blank(),
    ...sliceFunc("UnsignedPlaceholders", "string", sg.unsigned_placeholders, "UnsignedPlaceholders returns the signature segments the server accepts on unsigned URLs."),
    constGroup("Encryption constants.", [
      ["IVSize is the AES-CBC IV size in bytes.", "IVSize", N.int(en.iv_size)],
      ["EncryptedSourcePrefix starts an encrypted source segment.", "EncryptedSourcePrefix", str(en.source_prefix)],
      ["MaxPDFPasswordBytes is the longest PDF password, in UTF-8 bytes.", "MaxPDFPasswordBytes", N.int(en.max_pdf_password_bytes)],
      ["PDFPasswordName and PDFPasswordShort are the names of the PDF password option.", "PDFPasswordName", str(en.pdf_password_names[0]!)],
      ["", "PDFPasswordShort", str(en.pdf_password_short_name)],
    ]),
    blank(),
    ...sliceFunc("EncryptionKeySizes", "int", en.key_sizes, "EncryptionKeySizes returns the AES key sizes in bytes."),
    constGroup("URL grammar constants.", [
      ["DefaultSeparator separates an option's name and arguments (XI_DIALECTS_IMGPROXY_ARGUMENTS_SEPARATOR).", "DefaultSeparator", str(u.default_separator)],
      ["PipelineSeparator is the segment between chained pipelines.", "PipelineSeparator", str(u.pipeline_separator)],
      ["PlainSafe lists the characters a plain source keeps verbatim besides ASCII letters and digits.", "PlainSafe", str(u.plain_safe)],
      ["QuerySafe lists the characters a query key or value keeps verbatim besides ASCII letters and digits.", "QuerySafe", str(u.query_safe)],
      ["ExtensionPattern is the pattern of an output extension.", "ExtensionPattern", str(u.extension_pattern)],
    ]),
    blank(),
    ...sliceFunc("ForbiddenSeparators", "string", u.forbidden_separators, "ForbiddenSeparators returns the separators imgproxy URLs cannot use."),
    ...sliceFunc(
      "ForbiddenQuerySeparators",
      "string",
      u.forbidden_query_separators,
      "ForbiddenQuerySeparators returns the separators the query dialect's o= cannot use.",
    ),
  );

  // Error kinds.
  const kindConst = (k: string) => id(`ErrorKind${ident(k)}`);
  const kind = param("k", t("ErrorKind"));
  out.push(
    G.trailing(
      N.typeAlias("ErrorKind", t("string"), {
        doc: N.doc(
          "ErrorKind is the kind of the server's JSON error envelope. It is an error, so an *HTTPError\nmatches its kind with errors.Is (errors.Is(err, xtandard.ErrorKindNotFound)).",
        ),
      }),
      "nolint:errname // kinds are constant sentinels named like the server's kinds",
    ),
    blank(),
    G.group(
      "const",
      spec.error_kinds.map((k) =>
        N.const(`ErrorKind${ident(k.kind)}`, str(k.kind), { type: t("ErrorKind"), doc: N.doc(`ErrorKind${ident(k.kind)} is HTTP ${k.status}: ${k.message}.`) }),
      ),
      N.doc("Values of ErrorKind."),
    ),
    blank(),
    N.func("Error", [], [N.ret(N.call(id("string"), [id("k")]))], {
      receiver: kind,
      returns: t("string"),
      mods: ["inline"],
      doc: N.doc('Error implements error: the kind itself ("not_found").'),
    }),
    blank(),
    N.func(
      "ErrorKindFor",
      [param("status", t("int")), param("message", t("string"))],
      [
        switchOf(
          undefined,
          spec.error_kinds
            .filter((k) => k.kind !== "unknown")
            .map(
              (k) =>
                [
                  [N.binary("&&", N.binary("==", id("status"), N.int(k.status)), N.binary("==", id("message"), str(k.message)))],
                  [N.ret(kindConst(k.kind), N.bool(true))],
                ] as const,
            ),
        ),
        N.ret(id("ErrorKindUnknown"), N.bool(false)),
      ],
      {
        returns: N.ttuple([t("ErrorKind"), t("bool")]),
        doc: N.doc(
          "ErrorKindFor returns the error kind of a plain-text error response: the kind whose status and\npublic message match (the server writes the message alone when Accept does not list JSON).",
        ),
      },
    ),
    blank(),
    N.func(
      "Status",
      [],
      [switchOf(id("k"), spec.error_kinds.map((k) => [[str(k.kind)], [N.ret(N.int(k.status))]] as const)), N.ret(N.int(0))],
      { receiver: kind, returns: t("int"), doc: N.doc("Status returns the HTTP status the server answers an error kind with (0 for an unknown kind).") },
    ),
  );
  return N.file(out);
}

// ---- package xtandard: responses -----------------------------------------------

const scalars: Record<string, string> = { string: "string", integer: "int64", number: "float64", boolean: "bool" };

/** The Go type of a schema; optional fields are pointers (elem: a slice or map element, never a pointer). */
function schemaType(s: JSONSchema, optional: boolean, elem = false): TypeRef {
  const named = (name: string) => (optional && !elem ? ptr(name) : t(name));
  if (s.$ref) return elem ? t(refName(s.$ref)) : ptr(refName(s.$ref));
  if (s.enum) return named(s.enum.every((v) => typeof v === "string") && s.enum.includes("not_found") ? "ErrorKind" : "string");
  const ty = schemaTypes(s).filter((x) => x !== "null")[0];
  if (ty !== undefined && scalars[ty]) return named(scalars[ty]);
  if (ty === "array") return G.slice(s.items ? schemaType(s.items, false, true) : t("any"));
  if (ty === "object") {
    if (s.properties) throw new Error("inline object schemas are not supported");
    return G.map(t("string"), typeof s.additionalProperties === "object" ? schemaType(s.additionalProperties, false) : t("any"));
  }
  return t("any");
}

function emitResponses(spec: Spec): Node {
  const out: Node[] = [...header("xtandard", "JSON response bodies of the server (the OpenAPI components).")];
  for (const sm of responseSchemas(spec)) {
    const fields = sm.properties.map(([p, ps]) => {
      const optional = !sm.required.has(p);
      return N.field(ident(p), schemaType(ps, optional), {
        annotations: [N.annotation("json", [str(optional ? `${p},omitempty` : p)])],
        ...(ps.description ? { doc: N.doc(ps.description) } : {}),
      });
    });
    const doc = `${sm.name} is the ${sm.name} schema of the server's OpenAPI document.${sm.schema.description ? `\n\n${sm.schema.description}` : ""}`;
    out.push(N.type("struct", sm.name, fields, { doc: N.doc(doc) }), blank());
  }
  return N.file(out);
}

// ---- processing/, info/, video/: typed option values ----------------------------

interface FieldPlan {
  /** Go field name, or undefined for a fixed discriminator. */
  readonly field?: string;
  /** Go type of the field. */
  readonly type?: TypeRef;
  /** The argument (o.Field, core.Deref(o.Field) or a constant). */
  readonly expr: Expr;
  readonly doc: string;
}

function argDoc(a: SpecArg): string {
  const parts: string[] = [];
  if (a.doc) parts.push(a.doc.trim().replace(/\.$/, ""));
  if (a.enum && a.enum.length > 1) parts.push(`one of ${a.enum.join(", ")}`);
  if (a.min !== undefined || a.max !== undefined) {
    parts.push(`range ${a.min ?? "-∞"}${a.exclusive_min ? " (exclusive)" : ""} to ${a.max ?? "∞"}`);
  }
  if (a.multiple_of) parts.push(`a multiple of ${a.multiple_of}`);
  if (a.pattern) parts.push(`pattern ${a.pattern}`);
  return parts.join("; ");
}

function plural(name: string): string {
  return /(s|x|ch|sh)$/.test(name) ? `${name}es` : `${name}s`;
}

const isFixed = (a: SpecArg) => a.type === "enum" && a.enum?.length === 1;

function emitTyped(spec: Spec, kind: CatalogueKind): Node {
  const k = kindInfo[kind];
  const out: Node[] = [
    ...header(k.pkg, `Typed ${kind} options: one struct per option form, implementing xtandard.${k.iface}.`),
    G.imports([N.imp(module, [], { alias: "xtandard" }), N.imp(`${module}/internal/core`)]),
    blank(),
  ];
  const used = new Set<string>();
  const claim = (name: string, what: string) => {
    if (used.has(name)) throw new Error(`${kind}: the Go identifier ${name} (${what}) is used twice`);
    used.add(name);
  };
  const enumDecls: Node[] = [];
  const optionTypes: string[] = [];
  const enumOf = new Map<string, string>(); // option/arg -> type name

  const enumName = (o: OptionModel, a: SpecArg): string => {
    const key = `${o.name}/${a.name}`;
    const have = enumOf.get(key);
    if (have) return have;
    const base = ident(o.name);
    const an = ident(a.name);
    const name = an === base ? `${base}Value` : `${base}${an}`;
    claim(name, `enum ${key}`);
    enumOf.set(key, name);
    const consts = a.enum!.map((v) => {
      const c = `${name}${ident(v)}`;
      claim(c, `enum value ${key}=${v}`);
      return N.const(c, str(v), { type: t(name) });
    });
    enumDecls.push(
      N.typeAlias(name, t("string"), { doc: N.doc(`${name} is argument ${a.name} of ${kind} option ${o.name}: ${a.doc ?? a.name}.`) }),
      blank(),
      G.group("const", consts, N.doc(`Values of ${name}.`)),
      blank(),
    );
    return name;
  };

  const valueType = (o: OptionModel, a: SpecArg, optional: boolean): { type: TypeRef; ptr: boolean } => {
    const scalar = (name: string) => ({ type: optional ? ptr(name) : t(name), ptr: optional });
    switch (a.type) {
      case "integer":
        return scalar("int");
      case "number":
        return scalar("float64");
      case "boolean":
        return scalar("bool");
      case "enum":
        return { type: t(enumName(o, a)), ptr: false };
      default:
        // string, color, base64, direction: "" is an empty argument.
        return { type: t("string"), ptr: false };
    }
  };

  const recv = param("o", t("x"));
  for (const o of catalogue(spec, kind).options) {
    const base = ident(o.name);
    const forms = o.spec.forms;
    forms.forEach((f: SpecForm, fi: number) => {
      // Name: the option, then the discriminator value or the argument names.
      let name = base;
      if (fi > 0) {
        const disc = f.args.find(isFixed);
        name = disc ? `${base}${ident(disc.enum![0]!)}` : `${base}${ident(f.args.map((a) => a.name).join("_")) || `Form${fi}`}`;
      }
      claim(name, `${kind} option ${o.name} form ${fi}`);
      optionTypes.push(name);
      const min = Math.max(f.min_items, 1);
      const fields: FieldPlan[] = f.args.map((a, i) => {
        if (isFixed(a)) return { expr: str(a.enum![0]!), doc: "" };
        const fname = ident(a.name);
        const { type, ptr: isPtr } = valueType(o, a, a.nullable || i >= min);
        const value = N.get(id("o"), fname);
        return { field: fname, type, expr: isPtr ? N.call(sel("core", "Deref"), [value]) : value, doc: argDoc(a) };
      });
      const rest = f.rest ?? [];
      let restField: string | undefined;
      let restItem: string | undefined;
      if (rest.length === 1) {
        restField = ident(plural(rest[0]!.name));
      } else if (rest.length > 1) {
        restField = "Items";
        restItem = `${name}Item`;
        claim(restItem, `${kind} option ${o.name} rest item`);
      }
      const names = new Set<string>();
      for (const fp of fields) {
        if (fp.field === undefined) continue;
        if (names.has(fp.field)) throw new Error(`${kind} ${o.name}: field ${fp.field} twice`);
        names.add(fp.field);
      }
      if (restField && names.has(restField)) throw new Error(`${kind} ${o.name}: field ${restField} twice`);

      const formText =
        forms.length > 1
          ? `\n\nForm ${fi + 1} of ${forms.length}: ${f.args.map((a) => (isFixed(a) ? a.enum![0] : a.name)).join(":")}${rest.length ? `[:${rest.map((a) => a.name).join(":")}]…` : ""}.`
          : "";
      const members: Node[] = [];
      for (const fp of fields) {
        if (fp.field === undefined) continue;
        members.push(N.field(fp.field, fp.type, fp.doc ? { doc: N.doc(`${fp.field}: ${fp.doc}.`) } : {}));
      }
      let restElem: TypeRef | undefined;
      if (restField) {
        restElem = rest.length === 1 ? valueType(o, rest[0]!, false).type : t(restItem!);
        const restDoc =
          rest.length === 1
            ? `${restField}: the repeated ${rest[0]!.name} arguments${rest[0]!.doc ? ` (${argDoc(rest[0]!)})` : ""}.`
            : `${restField}: the repeated ${rest.map((a) => a.name).join(":")} groups.`;
        members.push(N.field(restField, G.slice(restElem), { doc: N.doc(restDoc) }));
      }
      out.push(N.type("struct", name, members, { doc: N.doc(`${name} is the ${kind} option ${o.name}: ${o.spec.doc}${formText}\n\n${optionSummary(o)}`) }), blank());
      if (rest.length > 1) {
        const itemFields = rest.map((a) =>
          N.field(ident(a.name), valueType(o, a, false).type, a.doc ? { doc: N.doc(`${ident(a.name)}: ${argDoc(a)}.`) } : {}),
        );
        out.push(N.type("struct", restItem!, itemFields, { doc: N.doc(`${restItem} is one repeated group of ${name}.`) }), blank());
      }
      const option = (args: Expr) => N.new(t("xtandard.Option"), [N.named("Name", str(o.name)), N.named("Args", args)]);
      const body: Stmt[] = [N.let("args", slice(t("xtandard.Arg"), fields.map((fp) => fp.expr)))];
      if (restField) {
        const restOf = N.get(id("o"), restField);
        const loop =
          rest.length === 1
            ? N.forEach("v", restOf, [N.let("args", N.call(id("append"), [id("args"), id("v")]), { mods: ["assign"] })])
            : N.forEach("it", restOf, [
                N.let("args", N.call(id("append"), [id("args"), ...rest.map((a) => N.get(id("it"), ident(a.name)))]), { mods: ["assign"] }),
              ]);
        body.push(N.if(N.binary(">", N.call(id("len"), [restOf]), N.int(0)), [loop, N.ret(option(id("args")))]));
      }
      body.push(N.ret(option(N.call(sel("core", "Trim"), [id("args"), N.int(min)]))));
      out.push(
        N.func(k.method, [], body, {
          receiver: { ...recv, type: t(name) },
          returns: t("xtandard.Option"),
          doc: N.doc(`${k.method} returns the option as xtandard.Option ${o.name} (unset trailing arguments are left out).`),
        }),
        blank(),
      );
    });
  }
  out.push(...enumDecls);
  out.push(
    G.group(
      "var",
      optionTypes.map((name) => N.const("_", N.new(t(name)), { type: t(`xtandard.${k.iface}`) })),
      N.doc("Compile-time checks: every option type implements the catalogue's interface."),
    ),
    blank(),
  );
  return N.file(out);
}

// ---- imgproxy/ and query/: fluent per-option methods ----------------------------

/** Control methods of the chains; a per-option method must not take one of these names. */
export const reservedMethods = new Set(["Option", "With", "Pipeline", "Extension", "Encoding", "WithPDFPassword", "Build", "Param", "Err"]);

function methods(spec: Spec, kind: CatalogueKind, chain: string): Node[] {
  const out: Node[] = [];
  const used = new Map<string, string>();
  const self = ptr(chain);
  for (const o of catalogue(spec, kind).options) {
    const argNames = o.args.map((a) => a.name);
    for (const n of o.names) {
      const name = ident(n);
      if (reservedMethods.has(name)) throw new Error(`${kind} option ${n} collides with the chain method ${name}`);
      const prev = used.get(name);
      if (prev !== undefined) throw new Error(`${kind} option names ${prev} and ${n} are both the Go method ${name}`);
      used.set(name, n);
      const what = n === o.name ? `${kind} option ${o.name}` : `${kind} option ${o.name} under its alias ${n}`;
      const doc = `${name} appends the ${what}: ${o.spec.doc}\n\nArguments: ${o.spec.syntax}${argNames.length ? ` (${[...new Set(argNames)].join(", ")})` : ""}. With GivenNames the option is written as ${JSON.stringify(n)}.`;
      out.push(
        N.func(name, [param("args", t("xtandard.Arg"), ["variadic"])], [N.ret(N.invoke(id("c"), "Option", [str(n), N.spread(id("args"))]))], {
          receiver: param("c", self),
          returns: self,
          doc: N.doc(doc),
        }),
        blank(),
      );
    }
  }
  return out;
}

function emitMethods(spec: Spec, pkg: string, chains: [CatalogueKind, string][]): Node {
  const out: Node[] = [
    ...header(pkg, "Per-option methods of the fluent URL chains: one per option name and alias."),
    N.imp(module, [], { alias: "xtandard" }),
    blank(),
  ];
  for (const [kind, chain] of chains) out.push(N.line(`---- ${chain}: ${kind} options ----`), blank(), ...methods(spec, kind, chain));
  return N.file(out);
}

export const emitter: Emitter = {
  language: "go",
  emit(spec) {
    const files: Record<string, Node> = {
      "zz_generated.go": emitRoot(spec),
      "zz_generated_responses.go": emitResponses(spec),
      "processing/zz_generated.go": emitTyped(spec, "processing"),
      "info/zz_generated.go": emitTyped(spec, "info"),
      "video/zz_generated.go": emitTyped(spec, "video"),
      "imgproxy/zz_generated_methods.go": emitMethods(spec, "imgproxy", [
        ["processing", "ImageChain"],
        ["info", "InfoChain"],
        ["video", "VideoChain"],
      ]),
      "query/zz_generated_methods.go": emitMethods(spec, "query", [
        ["processing", "ImageChain"],
        ["video", "VideoChain"],
      ]),
    };
    return Object.fromEntries(Object.entries(files).map(([f, n]) => [`${dir}${f}`, gofmt(`${dir}${f}`, printer.print(n))]));
  },
};
